class Calculator {
    int value = 0;

    Calculator add(int value) {
        this.value += value;
        return this;
    }

    Calculator multiply(int value) {
        this.value *= value;
        return this;
    }
}

public class Main {
    public static void main(String[] args) {
        Calculator calc = new Calculator();
        calc.add(5).multiply(3);
        System.out.println("Result: " + calc.value);
    }
}
